import { useCallback, useEffect, useState } from "react";
import { ArrowRight, Check, CheckCircle2, Clock3, Cpu, Database, HardDriveDownload, KeyRound, LifeBuoy, LockKeyhole, LogOut, Mail, Menu, MonitorCog, Plus, RefreshCw, Save, Search, Send, ShieldCheck, Sparkles, Sun, UserPlus, Users, Wrench, X } from "lucide-react";

const statuses = [
  { id: "contact-needed", label: "Contact needed", color: "red", description: "We have your request and will contact you." },
  { id: "ready-to-start", label: "Ready to start", color: "blue", description: "Your approval is signed and the order is ready." },
  { id: "in-progress", label: "In progress", color: "yellow", description: "Your device or request is being worked on." },
  { id: "completed", label: "Completed", color: "green", description: "The work is finished and ready for next steps." },
];
const contactOutcomes = [
  { id: "spoke", label: "Spoke with client" },
  { id: "left-voicemail", label: "Left voicemail" },
  { id: "no-connection", label: "No connection" },
];
const serviceChoices = [["Diagnostic and written estimate", 4900], ["Standard computer repair", 12900], ["Gaming PC repair", 16900], ["PC tune-up", 8900], ["PC cleaning", 6900], ["Malware or virus removal", 12900], ["Severe malware removal", 17900], ["Windows repair", 13900], ["Windows reinstall with data preservation", 17900], ["New computer setup", 12900], ["Data transfer", 14900], ["SSD or hard-drive installation", 7900], ["SSD installation with data migration", 14900], ["Custom PC assembly", 19900], ["Remote support", 7900], ["Onsite support", 11900], ["PC training and lessons", 6500]];
const services = [{ icon: HardDriveDownload, title: "Data transfers", body: "Move files, photos, accounts, and settings to a new PC or drive." }, { icon: MonitorCog, title: "PC tune-ups", body: "Improve startup time, remove clutter, update software, and check system health." }, { icon: Cpu, title: "Custom builds", body: "Parts selection and clean builds for gaming, work, creative apps, or everyday use." }, { icon: Wrench, title: "Repair work", body: "Troubleshoot hardware, Windows issues, network problems, and device failures." }, { icon: LifeBuoy, title: "PC training", body: "One-on-one lessons for Windows basics, files, email, apps, and safer everyday use." }, { icon: Sparkles, title: "PC cleaning", body: "Remove dust, clean the exterior, and check airflow so your PC can run cooler." }];
const pricingGroups = [{ title: "Common repairs", items: [["Diagnostic and written estimate", "$49", "Applied toward an approved repair within 30 days."], ["Standard computer repair", "From $129", "Common hardware and software repairs; final price follows diagnosis."], ["Gaming PC repair", "From $169", "Extra testing and component complexity included in the starting price."], ["PC tune-up", "$89", "Updates, cleanup, startup review, and a system health check."], ["PC cleaning", "$69", "Dust removal, exterior cleaning, and an airflow check."], ["Malware or virus removal", "$129", "Standard cleanup, security scan, updates, and final testing."], ["Windows repair", "From $139", "Repair system problems without a full reinstall when possible."]] }, { title: "Setup and upgrades", items: [["New computer setup", "$129", "Updates, accounts, security settings, printer connection, and basic apps."], ["Data transfer", "From $149", "Move accessible files, photos, browser data, and settings to a new device."], ["SSD or hard-drive installation", "$79 labor + parts", "Install and test a compatible drive; the drive is quoted separately."], ["SSD installation with data migration", "From $149 + drive", "Install the new drive and move accessible data from the old one."], ["Custom PC assembly", "From $199", "Assembly, BIOS setup, drivers, updates, and basic stability testing."]] }, { title: "Support and training", items: [["Remote support", "$79/hour", "Secure help for software, accounts, printers, and everyday PC problems."], ["Onsite support", "$119/hour", "One-hour minimum; travel included within the normal service area."], ["PC training and lessons", "$65/hour", "One-on-one help learning Windows, files, email, apps, and safe browsing."]] }];
const money = (cents) => Number.isInteger(Number(cents)) ? `$${(Number(cents) / 100).toFixed(2)}` : "Price to be confirmed";
const initialForm = { name: "", email: "", phone: "", assistance: "", company: "" };

function App() { const pathname = window.location.pathname; if (pathname.startsWith("/admin/reset")) return <ResetPassword />; if (pathname.startsWith("/admin")) return <AdminPortal />; if (pathname.startsWith("/account/setup")) return <AccountSetup />; if (pathname.startsWith("/account/verify")) return <AccountVerification />; if (pathname === "/account" || pathname.startsWith("/account/")) return <AccountPage />; if (pathname.startsWith("/orders/consent")) return <OrderConsent />; if (pathname === "/orders" || pathname.startsWith("/orders/")) return <OrdersPage />; return <CustomerSite />; }

function CustomerSite() { const [form, setForm] = useState(initialForm); const [notice, setNotice] = useState({ tone: "idle", text: "" }); const [ticket, setTicket] = useState(null); const [menuOpen, setMenuOpen] = useState(false); const [theme, setTheme] = useState(() => window.localStorage.getItem("repair-theme") || "dark"); useEffect(() => window.localStorage.setItem("repair-theme", theme), [theme]); const submitTicket = async (event) => { event.preventDefault(); setNotice({ tone: "idle", text: "Sending your request..." }); try { const response = await fetch("/api/contact", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) throw new Error(data.error || "The request could not be sent."); setTicket(data.contact); setForm(initialForm); setNotice({ tone: data.emailSent ? "success" : "idle", text: data.emailSent ? "Your message is in. I will get back to you." : "Your message is saved. I will get back to you." }); } catch (error) { setNotice({ tone: "error", text: error.message }); } }; const updateForm = (event) => { const { name, value } = event.target; setForm((current) => ({ ...current, [name]: value })); }; return <div className={`site-shell ${theme === "light" ? "theme-light" : "theme-dark"}`}><header className="public-header"><a href="#top" className="brand"><Brand /></a><div className="header-tools"><button className="theme-toggle" type="button" onClick={() => setTheme((current) => current === "dark" ? "light" : "dark")}>{theme === "dark" ? <Sun size={17} /> : "☾"}<span>{theme === "dark" ? "Light" : "Dark"}</span></button><button className="menu-button" type="button" aria-label="Toggle navigation" onClick={() => setMenuOpen((open) => !open)}>{menuOpen ? <X size={22} /> : <Menu size={22} />}</button></div><nav className={menuOpen ? "public-nav is-open" : "public-nav"}><a href="#services">Services</a><a href="#pricing">Pricing</a><a href="#how-it-works">How it works</a><a href="/orders">Orders</a><a className="nav-button" href="/account">Create account</a><a className="nav-button" href="#request">Contact me <ArrowRight size={16} /></a></nav></header><main><section className="hero-section" id="top"><div className="hero-grid"><div className="hero-copy"><p className="eyebrow"><span className="status-dot green" /> PC service · data transfers · repair</p><h1>Keep your files safe. Keep your PC moving.</h1><p className="hero-lede">Straightforward help for data transfers, PC tune-ups, custom builds, repair work, PC cleaning, and one-on-one training.</p><div className="hero-actions"><a className="button primary-button" href="#request">Contact me <ArrowRight size={18} /></a><a className="text-link" href="mailto:repair@nenosensei.com"><Mail size={17} /> repair@nenosensei.com</a></div><div className="trust-row"><span><ShieldCheck size={16} /> Privacy-minded handling</span><span><Clock3 size={16} /> Clear approval and status updates</span></div></div><div className="hero-panel"><div className="panel-header"><span>Service desk</span><span className="live-label"><span className="status-dot green" /> Online</span></div><div className="panel-screen"><div className="screen-row"><span className="screen-icon blue"><Database size={18} /></span><span><strong>Data transfer</strong><small>Move files to a new device</small></span><span className="screen-check"><Check size={16} /></span></div><div className="screen-row"><span className="screen-icon yellow"><MonitorCog size={18} /></span><span><strong>PC tune-up</strong><small>Speed and system health check</small></span><span className="screen-check"><Check size={16} /></span></div><div className="screen-row"><span className="screen-icon red"><Wrench size={18} /></span><span><strong>Repair work</strong><small>Hardware and Windows support</small></span><span className="screen-check"><Check size={16} /></span></div></div><div className="panel-foot"><LockKeyhole size={15} /> Client access is optional</div></div></div></section><section className="section services-section" id="services"><div className="section-heading"><p className="eyebrow">What we handle</p><h2>Useful help for the devices you use every day.</h2></div><div className="service-grid">{services.map(({ icon: Icon, title, body }) => <article className="service-card" key={title}><span className="service-icon"><Icon size={22} /></span><h3>{title}</h3><p>{body}</p><a href="#request">Request help <ArrowRight size={15} /></a></article>)}</div></section><section className="section pricing-section" id="pricing"><div className="section-heading"><p className="eyebrow">Straightforward pricing</p><h2>Know what to expect before work begins.</h2><p className="section-intro">We confirm final service prices with you before work starts. Parts, tax, and separately approved work are quoted separately.</p></div><div className="pricing-grid">{pricingGroups.map((group) => <article className="pricing-card" key={group.title}><h3>{group.title}</h3><div className="pricing-list">{group.items.map(([name, price, description]) => <div className="pricing-item" key={name}><div className="pricing-item-top"><strong>{name}</strong><span>{price}</span></div><p>{description}</p></div>)}</div></article>)}</div></section><section className="status-section" id="how-it-works"><div className="section status-layout"><div className="status-copy"><p className="eyebrow">Simple from start to finish</p><h2>Review and approve before work begins.</h2><p>We send the work order and current terms to you. Sign online when the details are correct, then follow progress through Orders.</p><a className="button ghost-button" href="#request">Start a ticket <ArrowRight size={17} /></a></div><div className="status-list">{statuses.map((status, index) => <div className="status-item" key={status.id}><span className={`status-number ${status.color}`}>0{index + 1}</span><div><div className="status-title"><span className={`status-dot ${status.color}`} />{status.label}</div><p>{status.description}</p></div></div>)}</div></div></section><section className="section request-section" id="request"><div className="request-layout"><div className="request-copy"><p className="eyebrow">Contact me</p><h2>Send a message</h2><p>Give me the basics and I will get back to you. This form is for contact requests; repair work orders are created separately.</p><div className="privacy-note"><LockKeyhole size={18} /><span><strong>Your information stays private.</strong><br />We only use these details to handle your service request.</span></div></div><form className="ticket-form" onSubmit={submitTicket}><label><span>Name</span><input required name="name" value={form.name} onChange={updateForm} autoComplete="name" placeholder="Your name" /></label><div className="form-row"><label><span>Email</span><input required name="email" type="email" value={form.email} onChange={updateForm} autoComplete="email" placeholder="you@example.com" /></label><label><span>Phone</span><input required name="phone" type="tel" value={form.phone} onChange={updateForm} autoComplete="tel" placeholder="(555) 555-5555" /></label></div><label><span>What can I help you with?</span><textarea required minLength="10" name="assistance" value={form.assistance} onChange={updateForm} rows="5" placeholder="Tell us about the device, files, or issue." /></label><input className="honeypot" tabIndex="-1" autoComplete="off" name="company" value={form.company} onChange={updateForm} aria-hidden="true" /><button className="button primary-button submit-button" type="submit">Contact me <Send size={17} /></button>{notice.text && <p className={`form-notice ${notice.tone}`} role="status">{notice.text}</p>}{ticket && <div className="ticket-confirmation"><CheckCircle2 size={22} /><div><strong>Contact request {ticket.id}</strong><span>Status: Contact needed.</span></div></div>}</form></div></section></main><footer className="public-footer"><div><a href="#top" className="brand"><Brand /></a><p>Data transfers, PC tune-ups, custom builds, repair work, PC cleaning, and PC training.</p></div><div className="footer-right"><a href="mailto:repair@nenosensei.com">repair@nenosensei.com</a><a href="/admin">Authorized admin</a></div></footer></div>; }

function AccountPanel() { const [customer, setCustomer] = useState(null); const [mode, setMode] = useState("register"); const [form, setForm] = useState({ name: "", email: "", phone: "", password: "" }); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const [verificationEmail, setVerificationEmail] = useState(""); useEffect(() => { fetch("/api/account/session").then(async (response) => { if (response.ok) setCustomer((await response.json()).customer); }).catch(() => {}); }, []); const submit = async (event) => { event.preventDefault(); setError(""); const endpoint = mode === "register" ? "/api/account/register" : "/api/account/login"; const response = await fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(mode === "register" ? form : { email: form.email, password: form.password }) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The account request could not be completed."); if (mode === "register" && data.verificationRequired) { setCustomer(null); setVerificationEmail(form.email); setMessage(data.emailSent ? "Check your email to verify your account before signing in." : "Your account was created, but the verification email could not be sent."); } else { setCustomer(data.customer); setMessage(mode === "register" ? "Your account is ready." : "You are signed in."); } setForm({ name: "", email: "", phone: "", password: "" }); }; const logout = async () => { await fetch("/api/account/logout", { method: "POST" }); setCustomer(null); setMessage("You have been signed out."); }; return <section className="section account-section" id="account"><div className="account-layout"><div className="account-copy"><p className="eyebrow">Customer account</p><h2>Keep your work orders in one place.</h2><p>Create an account to view work orders and sign approvals online. You can still send a request without signing up.</p><div className="privacy-note"><LockKeyhole size={18} /><span><strong>Account details are protected.</strong><br />Passwords are stored securely and never shown in the portal.</span></div></div>{customer ? <div className="account-card"><div className="account-card-heading"><div><p className="eyebrow">Signed in</p><h3>{customer.name}</h3><p>{customer.email}</p></div><button className="text-button" type="button" onClick={logout}>Sign out</button></div><p className="form-notice success">{message || "Your account is ready."}</p><a className="button primary-button" href="/orders">Open Orders <ArrowRight size={17} /></a></div> : <div className="account-card"><div className="account-tabs"><button type="button" className={mode === "register" ? "is-active" : ""} onClick={() => setMode("register")}>Create account</button><button type="button" className={mode === "login" ? "is-active" : ""} onClick={() => setMode("login")}>Sign in</button></div><form onSubmit={submit}>{mode === "register" && <><label><span>Name</span><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label><span>Phone <small>(optional)</small></span><input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></label></> }<label><span>Email</span><input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label><span>Password</span><input required minLength="12" type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} /></label><button className="button primary-button submit-button" type="submit">{mode === "register" ? "Create account" : "Sign in"} <ArrowRight size={17} /></button>{message && <p className="form-notice success">{message}</p>}{error && <p className="form-notice error">{error}</p>}{verificationEmail && mode === "register" && <button className="text-button" type="button" onClick={async () => { const response = await fetch("/api/account/resend-verification", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: verificationEmail }) }); const data = await response.json(); setMessage(response.ok ? "If the account needs verification, a new email has been sent." : data.error || "The verification email could not be requested."); }}>Resend verification email</button>}</form></div>}</div></section>; }

function OrdersPage() { const [customer, setCustomer] = useState(null); const [orders, setOrders] = useState([]); const [form, setForm] = useState({ email: "", password: "", name: "", phone: "" }); const [mode, setMode] = useState("login"); const [error, setError] = useState(""); const load = useCallback(async () => { const response = await fetch("/api/account/session"); if (!response.ok) return; const data = await response.json(); setCustomer(data.customer); const orderResponse = await fetch("/api/account/work-orders"); if (orderResponse.ok) setOrders((await orderResponse.json()).workOrders); }, []); useEffect(() => { load(); }, [load]); const submit = async (event) => { event.preventDefault(); setError(""); const response = await fetch(mode === "login" ? "/api/account/login" : "/api/account/register", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(mode === "login" ? { email: form.email, password: form.password } : form) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The account request could not be completed."); if (mode === "register" && data.verificationRequired) return setError(data.emailSent ? "Check your email to verify your account before signing in." : "Your account was created, but the verification email could not be sent."); setCustomer(data.customer); const orderResponse = await fetch("/api/account/work-orders"); if (orderResponse.ok) setOrders((await orderResponse.json()).workOrders); }; const sign = async (order) => { const response = await fetch(`/api/account/work-orders/${encodeURIComponent(order.id)}/consent-link`, { method: "POST" }); const data = await response.json(); if (!response.ok) return setError(data.error || "The approval link could not be created."); window.location.href = data.consentUrl; }; return <div className="site-shell theme-dark"><header className="public-header"><a href="/" className="brand"><Brand /></a><nav className="public-nav is-open"><a href="/">Services</a><a href="/#pricing">Pricing</a><a className="nav-button" href="/">Contact me <ArrowRight size={16} /></a></nav></header><main><section className="section orders-page"><div className="section-heading"><p className="eyebrow">Customer account</p><h1>Orders</h1><p className="section-intro">Review your work orders, prices, approval details, and current status.</p></div>{customer ? <div className="orders-list">{error && <p className="form-notice error" role="alert">{error}</p>}<div className="account-card account-card-heading"><div><p className="eyebrow">Signed in</p><h3>{customer.name}</h3><p>{customer.email}</p></div><button className="text-button" type="button" onClick={async () => { await fetch("/api/account/logout", { method: "POST" }); setCustomer(null); setOrders([]); }}>Sign out</button></div>{orders.length ? orders.map((order) => <CustomerWorkOrder key={order.id} order={order} onSign={() => sign(order)} />) : <div className="account-card"><p>Your work orders will appear here.</p></div>}</div> : <div className="account-card"><div className="account-tabs"><button type="button" className={mode === "register" ? "is-active" : ""} onClick={() => setMode("register")}>Create account</button><button type="button" className={mode === "login" ? "is-active" : ""} onClick={() => setMode("login")}>Sign in</button></div><form onSubmit={submit}>{mode === "register" && <><label><span>Name</span><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label><span>Phone</span><input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></label></>}<label><span>Email</span><input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label><span>Password</span><input required minLength="12" type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} /></label><button className="button primary-button submit-button" type="submit">{mode === "login" ? "Sign in" : "Create account"} <ArrowRight size={17} /></button>{error && <p className="form-notice error">{error}</p>}</form></div>}</section></main></div>; }

function CustomerWorkOrder({ order, onSign }) { const status = statuses.find((item) => item.id === order.status) || statuses[0]; return <article className="account-order-detail"><div className="account-order-heading"><div><strong>{order.id}</strong><span>{new Date(order.createdAt).toLocaleDateString()}</span></div><span className={`status-pill ${status.color}`}>{status.label}</span></div><div className="customer-order-details"><div><strong>Notes</strong><p>{order.notes || "No notes provided."}</p></div><div><strong>Device condition</strong><p>{order.deviceCondition || "Not recorded."}</p></div><div><strong>Accessories recorded by the shop</strong><p>{order.accessories || "None recorded."}</p></div><div><strong>Services and prices</strong>{order.services?.length ? <ul className="order-service-list">{order.services.map((item, index) => <li key={`${item.name}-${index}`}><span>{item.name}</span><span>{money(item.priceCents)}</span></li>)}</ul> : <p>No services listed.</p>}<strong className="order-total">Quoted service total: {money(order.totalCents)}</strong></div>{order.consent?.status === "signed" ? <div className="signed-details"><strong>Approved by {order.consent.signatureName}</strong><span>Signed {new Date(order.consent.signedAt).toLocaleString()} · Policy {order.consent.termsVersion}</span><span>Accessories left: {order.consent.accessoriesLeft ? "Yes" : "No"} · Data backup requested: {order.consent.backupRequested ? "Yes" : "No"}</span></div> : <div className="approval-callout"><strong>Approval required before repairs begin.</strong><button className="button primary-button" type="button" onClick={onSign}>Review and sign <ArrowRight size={16} /></button></div>}</div></article>; }

function AccountSetup() { const token = new URLSearchParams(window.location.search).get("token") || ""; const [customer, setCustomer] = useState(null); const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); useEffect(() => { fetch(`/api/account/setup?token=${encodeURIComponent(token)}`).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error); setCustomer(data.customer); }).catch((err) => setError(err.message)); }, [token]); const submit = async (event) => { event.preventDefault(); if (password !== confirm) return setError("The passwords do not match."); const response = await fetch("/api/account/setup-password", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token, password }) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The password could not be set."); window.location.href = "/orders"; }; return <SimplePage title="Finish your account setup"><p>{customer ? `Set a password for ${customer.email}.` : error || "Checking your setup link..."}</p>{customer && <form className="account-card" onSubmit={submit}><label><span>Password</span><input required minLength="12" type="password" value={password} onChange={(event) => setPassword(event.target.value)} /></label><label><span>Confirm password</span><input required minLength="12" type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} /></label><button className="button primary-button" type="submit">Set password <KeyRound size={17} /></button>{error && <p className="form-notice error">{error}</p>}</form>}</SimplePage>; }

function OrderConsent() { const token = new URLSearchParams(window.location.search).get("token") || ""; const [consent, setConsent] = useState(null); const [form, setForm] = useState({ signatureName: "", termsAccepted: false, electronicRecordsAccepted: false, accessoriesAcknowledged: false, accessoriesLeft: "", backupRequested: "" }); const [error, setError] = useState(""); const [done, setDone] = useState(false); useEffect(() => { fetch(`/api/account/consent?token=${encodeURIComponent(token)}`).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error); setConsent(data.consent); }).catch((err) => setError(err.message)); }, [token]); const submit = async (event) => { event.preventDefault(); const response = await fetch("/api/account/consent", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token, ...form, accessoriesLeft: form.accessoriesLeft === "yes" ? true : form.accessoriesLeft === "no" ? false : null, backupRequested: form.backupRequested === "yes" ? true : form.backupRequested === "no" ? false : null }) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The approval could not be submitted."); setDone(true); }; if (done) return <SimplePage title="Approval received"><p className="form-notice success">Your signature was saved. The work order is now Ready to start.</p><a className="button primary-button" href="/orders">Open Orders <ArrowRight size={17} /></a></SimplePage>; return <SimplePage title="Review and approve your work order"><p>{consent ? `Work order ${consent.workOrder.id} for ${consent.workOrder.name}.` : error || "Loading work order..."}</p>{consent && <form className="consent-card" onSubmit={submit}><div className="consent-summary"><InfoBlock title="Notes" value={consent.workOrder.notes} /><InfoBlock title="Device condition" value={consent.workOrder.deviceCondition} /><InfoBlock title="Accessories recorded by the shop" value={consent.workOrder.accessories || "None recorded."} /><div><strong>Services and prices</strong><ul className="order-service-list">{consent.workOrder.services.map((item, index) => <li key={`${item.name}-${index}`}><span>{item.name}</span><span>{money(item.priceCents)}</span></li>)}</ul><strong className="order-total">Quoted service total: {money(consent.workOrder.totalCents)}</strong></div></div><div className="terms-box"><div className="terms-box-heading"><strong>Terms and liability policy — {consent.terms.version}</strong><button className="text-button" type="button" onClick={() => window.print()}>Print / save</button></div><p>{consent.terms.body}</p></div><label><span>Full legal name</span><input required value={form.signatureName} onChange={(event) => setForm({ ...form, signatureName: event.target.value })} placeholder="Enter your full legal name" /></label><label className="check-row"><input required type="checkbox" checked={form.termsAccepted} onChange={(event) => setForm({ ...form, termsAccepted: event.target.checked })} /><span>I agree to the terms and liability policy shown above.</span></label><label className="check-row"><input required type="checkbox" checked={form.electronicRecordsAccepted} onChange={(event) => setForm({ ...form, electronicRecordsAccepted: event.target.checked })} /><span>I consent to receive and retain this work order electronically.</span></label><fieldset><legend>Are you leaving accessories with the device?</legend><label className="check-row"><input required type="radio" name="accessories" value="yes" checked={form.accessoriesLeft === "yes"} onChange={(event) => setForm({ ...form, accessoriesLeft: event.target.value, accessoriesAcknowledged: true })} />Yes, accessories are being left</label><label className="check-row"><input required type="radio" name="accessories" value="no" checked={form.accessoriesLeft === "no"} onChange={(event) => setForm({ ...form, accessoriesLeft: event.target.value, accessoriesAcknowledged: true })} />No accessories are being left</label></fieldset><fieldset><legend>Do you want a data backup?</legend><label className="check-row"><input required type="radio" name="backup" value="yes" checked={form.backupRequested === "yes"} onChange={(event) => setForm({ ...form, backupRequested: event.target.value })} />Yes, backup requested</label><label className="check-row"><input required type="radio" name="backup" value="no" checked={form.backupRequested === "no"} onChange={(event) => setForm({ ...form, backupRequested: event.target.value })} />No backup requested</label></fieldset><button className="button primary-button" type="submit">Sign and approve work order <Check size={17} /></button>{error && <p className="form-notice error">{error}</p>}</form>}</SimplePage>; }
function InfoBlock({ title, value }) { return <div><strong>{title}</strong><p>{value || "Not recorded."}</p></div>; }
function SimplePage({ title, children }) { return <div className="site-shell theme-dark"><header className="public-header"><a href="/" className="brand"><Brand /></a></header><main><section className="section standalone-page"><div className="section-heading"><p className="eyebrow">Neno&apos;s IT repair</p><h1>{title}</h1></div>{children}</section></main></div>; }

function AdminPortal() { const [session, setSession] = useState(null); const [loading, setLoading] = useState(true); const [loginForm, setLoginForm] = useState({ username: "", password: "" }); const [loginError, setLoginError] = useState(""); const [forgot, setForgot] = useState(false); const [forgotId, setForgotId] = useState(""); const [forgotMessage, setForgotMessage] = useState(""); const [orders, setOrders] = useState([]); const [contacts, setContacts] = useState([]); const [search, setSearch] = useState(""); const [filter, setFilter] = useState("all"); const [section, setSection] = useState("work-orders"); const [message, setMessage] = useState(""); const loadOrders = useCallback(async (query = "") => { const response = await fetch(`/api/admin/work-orders?search=${encodeURIComponent(query)}`); if (response.ok) setOrders((await response.json()).workOrders); }, []); const loadContacts = useCallback(async (query = "") => { const response = await fetch(`/api/admin/contacts?search=${encodeURIComponent(query)}`); if (response.ok) setContacts((await response.json()).contacts); }, []); useEffect(() => { fetch("/api/admin/session").then(async (response) => { if (!response.ok) throw new Error(); const data = await response.json(); setSession(data); await loadOrders(); }).catch(() => {}).finally(() => setLoading(false)); }, [loadOrders]); useEffect(() => { if (!session || !["work-orders", "contacts"].includes(section)) return undefined; const timer = setTimeout(() => section === "contacts" ? loadContacts(search) : loadOrders(search), 250); return () => clearTimeout(timer); }, [search, session, section, loadOrders, loadContacts]); const login = async (event) => { event.preventDefault(); setLoginError(""); const response = await fetch("/api/admin/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(loginForm) }); const data = await response.json(); if (!response.ok) return setLoginError(data.error || "Login failed."); setSession(await (await fetch("/api/admin/session")).json()); await loadOrders(); }; const updateStatus = async (id, status) => { const response = await fetch(`/api/admin/work-orders/${encodeURIComponent(id)}`, { method: "PATCH", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify({ status }) }); const data = await response.json(); if (!response.ok) return setMessage(data.error || "The status could not be updated."); setOrders((current) => current.map((order) => order.id === id ? data.workOrder : order)); setMessage(data.emailSent ? "Work order updated and email sent." : "Work order updated. Email delivery is not configured or failed."); }; const updateContactStatus = async (id, status) => { const response = await fetch(`/api/admin/contacts/${encodeURIComponent(id)}`, { method: "PATCH", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify({ status }) }); const data = await response.json(); if (!response.ok) return setMessage(data.error || "The contact status could not be updated."); setContacts((current) => current.map((contact) => contact.id === id ? data.contact : contact)); setMessage("Contact request updated."); }; const logContact = async (id, details) => { const response = await fetch(`/api/admin/work-orders/${encodeURIComponent(id)}/contact-log`, { method: "POST", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify(details) }); const data = await response.json(); if (!response.ok) { setMessage(data.error || "The contact could not be logged."); return false; } setOrders((current) => current.map((order) => order.id === id ? data.workOrder : order)); setMessage("Contact logged."); return true; }; const deleteOrder = async (id) => { if (!window.confirm(`Delete work order ${id}? This cannot be undone.`)) return; const response = await fetch(`/api/admin/work-orders/${encodeURIComponent(id)}`, { method: "DELETE", headers: { "X-CSRF-Token": session.csrfToken } }); if (response.ok) { setOrders((current) => current.filter((order) => order.id !== id)); setMessage(`Work order ${id} was deleted.`); } }; const logout = async () => { await fetch("/api/admin/logout", { method: "POST", headers: { "X-CSRF-Token": session.csrfToken } }); setSession(null); }; if (loading) return <div className="admin-shell"><div className="admin-loading">Loading admin portal...</div></div>; if (!session) return <AdminLogin {...{ forgot, setForgot, forgotId, setForgotId, forgotMessage, setForgotMessage, loginForm, setLoginForm, loginError, login, setLoginError }} />; const visible = filter === "all" ? orders : orders.filter((order) => order.status === filter); const counts = statuses.reduce((result, status) => ({ ...result, [status.id]: orders.filter((order) => order.status === status.id).length }), {}); return <div className="admin-shell"><header className="admin-header"><a className="brand" href="/"><Brand /></a><div><span className="admin-user">{session.user?.name || "Signed in"}</span><button className="icon-button" type="button" onClick={logout} aria-label="Sign out"><LogOut size={18} /></button></div></header><main className="admin-main"><div className="admin-title"><div><p className="eyebrow">Private workspace</p><h1>Business records</h1><p>Manage work orders, customer accounts, terms, and staff access.</p></div><button className="button ghost-button" type="button" onClick={() => section === "contacts" ? loadContacts(search) : loadOrders(search)}><RefreshCw size={16} /> Refresh</button></div><div className="admin-nav-tabs"><button className={section === "work-orders" ? "is-active" : ""} type="button" onClick={() => setSection("work-orders")}><Wrench size={16} /> Work orders</button><button className={section === "contacts" ? "is-active" : ""} type="button" onClick={() => setSection("contacts")}><Mail size={16} /> Contact requests</button><button className={section === "customers" ? "is-active" : ""} type="button" onClick={() => setSection("customers")}><Users size={16} /> Customers</button>{session.user?.role === "owner" && <><button className={section === "terms" ? "is-active" : ""} type="button" onClick={() => setSection("terms")}><ShieldCheck size={16} /> Terms</button><button className={section === "staff" ? "is-active" : ""} type="button" onClick={() => setSection("staff")}><UserPlus size={16} /> Staff access</button></>}</div>{section === "work-orders" && <><div className="admin-stat-grid">{statuses.map((status) => <StatCard key={status.id} color={status.color} label={status.label} value={counts[status.id] || 0} />)}</div><div className="ticket-toolbar"><div><h2>Work orders</h2><p>{visible.length} shown</p></div><div className="work-order-tools"><label className="search-field"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search number, name, email..." /></label><select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">All statuses</option>{statuses.map((status) => <option key={status.id} value={status.id}>{status.label}</option>)}</select></div></div>{message && <p className="admin-message">{message}</p>}<div className="admin-ticket-list">{visible.length ? visible.map((order) => <AdminTicket key={order.id} ticket={order} onStatusChange={updateStatus} onDelete={deleteOrder} onLogContact={logContact} />) : <div className="admin-empty"><LifeBuoy size={28} /><h3>No work orders here</h3></div>}</div></>}{section === "contacts" && <ContactManager contacts={contacts} onStatusChange={updateContactStatus} />} {section === "customers" && <CustomerManager session={session} setMessage={setMessage} />}{section === "terms" && <TermsManager session={session} setMessage={setMessage} />}{section === "staff" && <StaffManager session={session} setMessage={setMessage} />}</main></div>; }

function AdminLogin({ forgot, setForgot, forgotId, setForgotId, forgotMessage, setForgotMessage, loginForm, setLoginForm, loginError, login, setLoginError }) { const requestReset = async (event) => { event.preventDefault(); const response = await fetch("/api/admin/forgot-password", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username: forgotId }) }); const data = await response.json(); setForgotMessage(data.message || "If the account is valid, a reset link will arrive shortly."); }; return <div className="admin-shell"><div className="admin-login"><a className="brand" href="/"><Brand /></a><div className="admin-login-card"><p className="eyebrow">Authorized access</p>{forgot ? <><h1>Reset password</h1><p>Enter your staff username or email. If it is valid, a reset link will be sent.</p><form onSubmit={requestReset}><label><span>Username or email</span><input required value={forgotId} onChange={(event) => setForgotId(event.target.value)} /></label><button className="button primary-button submit-button" type="submit">Email reset link <Mail size={17} /></button>{forgotMessage && <p className="form-notice success">{forgotMessage}</p>}</form><button className="text-button" type="button" onClick={() => { setForgot(false); setForgotMessage(""); }}>Back to sign in</button></> : <><h1>Business records</h1><p>Sign in to manage work orders and customer information.</p><form onSubmit={login}><label><span>Username</span><input required value={loginForm.username} onChange={(event) => setLoginForm({ ...loginForm, username: event.target.value })} /></label><label><span>Password</span><input required type="password" value={loginForm.password} onChange={(event) => setLoginForm({ ...loginForm, password: event.target.value })} /></label><button className="button primary-button submit-button" type="submit">Sign in <ArrowRight size={17} /></button>{loginError && <p className="form-notice error">{loginError}</p>}</form><button className="text-button" type="button" onClick={() => { setForgot(true); setLoginError(""); }}>Forgot password?</button></>}</div><a className="admin-back" href="/">← Back to customer site</a></div></div>; }

function ContactManager({ contacts, onStatusChange }) { return <div className="records-panel"><div className="records-heading"><div><h2>Contact requests</h2><p>These messages are kept separate from repair work orders. Each request remains Contact needed until it is handled.</p></div></div><div className="record-list">{contacts.length ? contacts.map((contact) => <article className="contact-record" key={contact.id}><div className="admin-order-row-top"><div><strong className="ticket-id">{contact.id}</strong><h3>{contact.name}</h3></div><span className={`status-pill ${contact.status === "completed" ? "green" : "red"}`}>{contact.status === "completed" ? "Completed" : "Contact needed"}</span></div><div className="ticket-meta"><a href={`mailto:${contact.email}`}><Mail size={15} />{contact.email}</a><a href={`tel:${contact.phone}`}><Clock3 size={15} />{contact.phone}</a></div><p className="ticket-request">{contact.message}</p><div className="status-actions"><button className={`status-choice ${contact.status === "contact-needed" ? "is-selected red" : ""}`} type="button" onClick={() => onStatusChange(contact.id, "contact-needed")}>Contact needed</button><button className={`status-choice ${contact.status === "completed" ? "is-selected green" : ""}`} type="button" onClick={() => onStatusChange(contact.id, "completed")}>Mark handled</button></div></article>) : <p className="account-empty">No contact requests match this search.</p>}</div></div>; }

function CustomerManager({ session, setMessage }) { const [customers, setCustomers] = useState([]); const [search, setSearch] = useState(""); const [selected, setSelected] = useState(null); const [orders, setOrders] = useState([]); const [form, setForm] = useState({ name: "", email: "", phone: "" }); const [editing, setEditing] = useState(null); const [editingOrder, setEditingOrder] = useState(null); const [editorOpen, setEditorOpen] = useState(false); const load = useCallback(async (query = "") => { const response = await fetch(`/api/admin/customers?search=${encodeURIComponent(query)}`); if (response.ok) setCustomers((await response.json()).customers); }, []); useEffect(() => { const timer = setTimeout(() => load(search), 200); return () => clearTimeout(timer); }, [search, load]); const select = async (customer) => { const response = await fetch(`/api/admin/customers/${customer.id}`); if (!response.ok) return; const data = await response.json(); setSelected(data.customer); setOrders(data.workOrders); setForm({ name: data.customer.name, email: data.customer.email, phone: data.customer.phone }); setEditing(data.customer); setEditorOpen(false); }; const save = async (event) => { event.preventDefault(); const endpoint = editing ? `/api/admin/customers/${editing.id}` : "/api/admin/customers"; const response = await fetch(endpoint, { method: editing ? "PATCH" : "POST", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) return setMessage(data.error || "The customer account could not be saved."); setMessage(data.inviteSent === false ? "Customer account created, but the invitation email could not be sent." : editing ? "Customer account updated." : "Customer account created and invitation sent."); if (data.customer) await select(data.customer); await load(search); }; const newCustomer = () => { setSelected(null); setOrders([]); setEditing(null); setForm({ name: "", email: "", phone: "" }); setEditorOpen(false); }; const resend = async () => { const response = await fetch(`/api/admin/customers/${selected.id}/invite`, { method: "POST", headers: { "X-CSRF-Token": session.csrfToken } }); const data = await response.json(); setMessage(data.inviteSent ? "Invitation sent again." : "Invitation created, but email delivery failed."); }; const saveOrder = (order) => { setOrders((current) => editingOrder ? current.map((item) => item.id === order.id ? order : item) : [order, ...current]); setEditorOpen(false); setEditingOrder(null); setMessage(`Work order ${order.id} saved.`); }; return <div className="customer-manager"><div className="records-panel"><div className="records-heading"><div><h2>Customer accounts</h2><p>Search by name, email, or phone, then open the account.</p></div><button className="button primary-button" type="button" onClick={newCustomer}><Plus size={16} /> New customer</button></div><label className="record-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search name, email, or phone" /></label><div className="record-list">{customers.length ? customers.map((customer) => <button className={`record-row record-row-button ${selected?.id === customer.id ? "is-selected" : ""}`} type="button" key={customer.id} onClick={() => select(customer)}><div><strong>{customer.name}</strong><span>{customer.email}{customer.phone ? ` · ${customer.phone}` : ""}</span></div><span className="record-count">{customer.pendingPassword ? "Invitation pending" : `${customer.workOrderCount || 0} work orders`}</span></button>) : <p className="account-empty">No customer accounts match that search.</p>}</div></div><div className="records-panel"><div className="records-heading"><div><h2>{editing ? "Customer details" : "New customer"}</h2><p>{editing ? "Update the account or resend its password setup email." : "The customer will receive a one-time password setup email."}</p></div></div><form className="record-form" onSubmit={save}><label><span>Name</span><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label><span>Email</span><input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label><span>Phone</span><input value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} /></label><div className="record-actions"><button className="button primary-button" type="submit"><Check size={16} />{editing ? "Save customer" : "Create and invite"}</button>{editing && selected?.pendingPassword && <button className="button ghost-button" type="button" onClick={resend}>Resend invitation</button>}</div></form></div>{selected && <div className="records-panel customer-work-orders"><div className="records-heading"><div><p className="eyebrow">Selected customer</p><h2>{selected.name}</h2><p>{selected.email}{selected.phone ? ` · ${selected.phone}` : ""}</p></div><button className="button primary-button" type="button" onClick={() => { setEditingOrder(null); setEditorOpen(true); }}><Plus size={16} /> Create work order</button></div>{editorOpen ? <WorkOrderEditor customer={selected} order={editingOrder} session={session} onSaved={saveOrder} onCancel={() => { setEditorOpen(false); setEditingOrder(null); }} /> : <div className="record-list">{orders.length ? orders.map((order) => <AdminOrderRow key={order.id} order={order} onEdit={() => { setEditingOrder(order); setEditorOpen(true); }} />) : <p className="account-empty">No work orders are attached to this account.</p>}</div>}</div>}</div>; }

function WorkOrderEditor({ customer, order, session, onSaved, onCancel }) { const [form, setForm] = useState(() => workOrderForm(order)); const [choice, setChoice] = useState(""); const [customName, setCustomName] = useState(""); const [customPrice, setCustomPrice] = useState(""); const [error, setError] = useState(""); useEffect(() => setForm(workOrderForm(order)), [order]); const field = (name, value) => setForm((current) => ({ ...current, [name]: value })); const addChoice = () => { const item = serviceChoices.find(([name]) => name === choice); if (!item) return; setForm((current) => ({ ...current, services: [...current.services, { name: item[0], priceCents: item[1] }] })); setChoice(""); }; const addCustom = () => { const name = customName.trim(); const price = Number(customPrice); if (!name || !Number.isFinite(price) || price < 0) return; setForm((current) => ({ ...current, services: [...current.services, { name, priceCents: Math.round(price * 100) }] })); setCustomName(""); setCustomPrice(""); }; const submit = async (event) => { event.preventDefault(); setError(""); const endpoint = order ? `/api/admin/work-orders/${encodeURIComponent(order.id)}` : `/api/admin/customers/${customer.id}/work-orders`; const response = await fetch(endpoint, { method: order ? "PATCH" : "POST", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify({ notes: form.notes, repairNotes: form.repairNotes, deviceCondition: form.deviceCondition, accessories: form.accessories, services: form.services, ...(order ? { status: form.status } : {}) }) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The work order could not be saved."); onSaved(data.workOrder); }; return <form className="work-order-editor" onSubmit={submit}><div className="editor-heading"><div><p className="eyebrow">{order ? "Edit work order" : "New work order"}</p><h3>{order ? order.id : `For ${customer.name}`}</h3><p>{order ? "Changes to customer-facing details require approval again." : `${customer.email}${customer.phone ? ` · ${customer.phone}` : ""}`}</p></div><button className="text-button" type="button" onClick={onCancel}>Cancel</button></div><div className="work-order-fields"><label><span>Notes <small>Required</small></span><textarea required value={form.notes} onChange={(event) => field("notes", event.target.value)} rows="4" placeholder="Describe the client issue or requested work." /></label><label><span>Repair notes <small>Private</small></span><textarea value={form.repairNotes} onChange={(event) => field("repairNotes", event.target.value)} rows="4" placeholder="Only authorized admin staff can see this." /></label><label><span>Device condition <small>Required at check-in</small></span><textarea required value={form.deviceCondition} onChange={(event) => field("deviceCondition", event.target.value)} rows="4" placeholder="Describe the condition when received." /></label><label><span>Accessories</span><textarea value={form.accessories} onChange={(event) => field("accessories", event.target.value)} rows="3" placeholder="List chargers, cables, cases, or other items received." /></label></div><fieldset className="service-selector"><legend>Services and prices</legend><p>Choose a service, set its price for this order, or add a custom line.</p><div className="service-add-row"><select value={choice} onChange={(event) => setChoice(event.target.value)}><option value="">Choose a service</option>{serviceChoices.map(([name, price]) => <option key={name} value={name}>{name} — {money(price)}</option>)}</select><button className="button ghost-button" type="button" onClick={addChoice}><Plus size={15} /> Add</button></div><div className="line-items">{form.services.map((service, index) => <div className="line-item" key={`${service.name}-${index}`}><input aria-label={`Service ${index + 1} name`} value={service.name} onChange={(event) => setForm((current) => ({ ...current, services: current.services.map((item, itemIndex) => itemIndex === index ? { ...item, name: event.target.value } : item) }))} /><div className="price-input"><span>$</span><input aria-label={`Service ${index + 1} price`} type="number" min="0" step="0.01" value={service.priceCents === null ? "" : (service.priceCents / 100).toFixed(2)} onChange={(event) => setForm((current) => ({ ...current, services: current.services.map((item, itemIndex) => itemIndex === index ? { ...item, priceCents: event.target.value === "" ? null : Math.round(Number(event.target.value) * 100) } : item) }))} /></div><button className="icon-button" type="button" onClick={() => setForm((current) => ({ ...current, services: current.services.filter((_item, itemIndex) => itemIndex !== index) }))} aria-label={`Remove ${service.name}`}><X size={16} /></button></div>)}</div><div className="custom-service-input"><input value={customName} onChange={(event) => setCustomName(event.target.value)} placeholder="Custom service name" /><input type="number" min="0" step="0.01" value={customPrice} onChange={(event) => setCustomPrice(event.target.value)} placeholder="Price" /><button className="button ghost-button" type="button" onClick={addCustom}><Plus size={15} /> Add custom</button></div><strong className="order-total">Quoted total: {money(form.services.reduce((sum, item) => sum + (Number.isInteger(item.priceCents) ? item.priceCents : 0), 0))}</strong></fieldset>{order && <label className="status-field"><span>Status</span><select value={form.status} onChange={(event) => field("status", event.target.value)}>{statuses.filter((status) => status.id !== "ready-to-start").map((status) => <option key={status.id} value={status.id}>{status.label}</option>)}</select></label>}{error && <p className="form-notice error">{error}</p>}<div className="editor-actions"><button className="button primary-button" type="submit"><Save size={16} />{order ? "Save work order" : "Create work order"}</button><button className="button ghost-button" type="button" onClick={onCancel}>Cancel</button></div></form>; }
function workOrderForm(order) { return { notes: order?.notes || order?.assistance || "", repairNotes: order?.repairNotes || "", deviceCondition: order?.deviceCondition || "", accessories: order?.accessories || "", services: order?.services || [], status: order?.status || "contact-needed" }; }
function AdminOrderRow({ order, onEdit }) { const status = statuses.find((item) => item.id === order.status) || statuses[0]; return <article className="admin-order-row"><div className="admin-order-row-top"><div><strong className="ticket-id">{order.id}</strong><h3>{order.name}</h3></div><span className={`status-pill ${status.color}`}>{status.label}</span></div><p className="ticket-request">{order.notes || order.assistance}</p><div className="order-detail-grid">{order.deviceCondition && <div><strong>Device condition</strong><span>{order.deviceCondition}</span></div>}{order.services?.length > 0 && <div><strong>Services</strong><span>{order.services.map((item) => `${item.name} (${money(item.priceCents)})`).join(", ")}</span></div>}{order.adminConsent?.status === "signed" && <div><strong>Signed approval</strong><span>{order.adminConsent.signatureName} · {new Date(order.adminConsent.signedAt).toLocaleString()}</span></div>}{order.repairNotes && <div><strong>Repair notes</strong><span>{order.repairNotes}</span></div>}</div><button className="text-button" type="button" onClick={onEdit}>Edit work order</button></article>; }
function AdminTicket({ ticket, onStatusChange, onDelete, onLogContact }) { const status = statuses.find((item) => item.id === ticket.status) || statuses[0]; const [contactForm, setContactForm] = useState({ outcome: "spoke", notes: "" }); const submitContact = async (event) => { event.preventDefault(); const saved = await onLogContact(ticket.id, contactForm); if (saved) setContactForm({ outcome: "spoke", notes: "" }); }; return <article className="admin-ticket"><div className="admin-ticket-top"><div><span className="ticket-id">{ticket.id}</span><h3>{ticket.name}</h3></div><span className={`status-pill ${status.color}`}><span className="status-dot" />{status.label}</span></div><div className="ticket-meta"><a href={`mailto:${ticket.email}`}><Mail size={15} />{ticket.email}</a><a href={`tel:${ticket.phone}`}><Clock3 size={15} />{ticket.phone}</a></div><p className="ticket-request">{ticket.notes}</p><div className="order-detail-grid"><div><strong>Quoted total</strong><span>{money(ticket.totalCents)}</span></div>{ticket.adminConsent?.status === "signed" ? <div><strong>Approval</strong><span>Signed by {ticket.adminConsent.signatureName} on {new Date(ticket.adminConsent.signedAt).toLocaleString()}</span></div> : <div><strong>Approval</strong><span>Customer signature required</span></div>}</div>{ticket.status === "completed" && ticket.daysSinceCompleted !== null && <p className="completion-counter">Completed {ticket.daysSinceCompleted} {ticket.daysSinceCompleted === 1 ? "day" : "days"} ago</p>}<div className="contact-log-section"><div className="contact-log-heading"><div><strong>Call log</strong><span>{ticket.lastContactedAt ? `Last contacted ${new Date(ticket.lastContactedAt).toLocaleString()} · ${ticket.lastContactOutcome === "spoke" ? "Spoke with client" : ticket.lastContactOutcome === "left-voicemail" ? "Left voicemail" : "No connection"}` : "No contact logged yet"}</span></div></div>{ticket.contactLogs?.length ? <div className="contact-log-list">{ticket.contactLogs.map((log) => <div className="contact-log-entry" key={log.id}><div><strong>{log.outcomeLabel}</strong><span>{new Date(log.contactedAt).toLocaleString()} · {log.staffName}</span></div><p>{log.notes}</p></div>)}</div> : <p className="contact-log-empty">Record each call or attempted call here.</p>}<form className="contact-log-form" onSubmit={submitContact}><label><span>Contact result</span><select value={contactForm.outcome} onChange={(event) => setContactForm({ ...contactForm, outcome: event.target.value })}>{contactOutcomes.map((outcome) => <option key={outcome.id} value={outcome.id}>{outcome.label}</option>)}</select></label><label><span>What was the call about?</span><textarea required minLength="1" rows="2" value={contactForm.notes} onChange={(event) => setContactForm({ ...contactForm, notes: event.target.value })} placeholder="Add a short note about the call or attempted call." /></label><button className="button ghost-button" type="submit">Log contact <Check size={16} /></button></form></div><div className="status-actions">{statuses.filter((option) => option.id !== "ready-to-start").map((option) => <button key={option.id} type="button" className={ticket.status === option.id ? `status-choice is-selected ${option.color}` : "status-choice"} onClick={() => onStatusChange(ticket.id, option.id)}>{ticket.status === option.id && <Check size={14} />}{option.label}</button>)}<button className="status-choice danger-choice" type="button" onClick={() => onDelete(ticket.id)}>Delete</button></div></article>; }
function TermsManager({ session, setMessage }) { const [terms, setTerms] = useState([]); const [body, setBody] = useState(""); const load = async () => { const response = await fetch("/api/admin/terms"); if (response.ok) { const data = await response.json(); setTerms(data.terms); if (!body) setBody(data.published?.body || data.terms.find((item) => item.status === "draft")?.body || ""); } }; useEffect(() => { load(); // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); const publish = async (event) => { event.preventDefault(); const response = await fetch("/api/admin/terms", { method: "POST", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify({ body }) }); const data = await response.json(); if (!response.ok) return setMessage(data.error || "The terms could not be published."); setMessage(`Terms ${data.terms.version} published.`); await load(); }; return <div className="records-panel terms-manager"><div className="records-heading"><div><h2>Terms and liability policy</h2><p>Draft policies are not in effect. Review the policy carefully, then publish a reviewed version before sending approval requests.</p></div></div><form className="record-form" onSubmit={publish}><label><span>Current policy text</span><textarea required minLength="100" rows="18" value={body} onChange={(event) => setBody(event.target.value)} /></label><button className="button primary-button" type="submit"><Check size={16} /> Publish new version</button></form><div className="record-list">{terms.map((item) => <div className="record-row" key={item.id}><div><strong>{item.version} <span className="role-badge">{item.status}</span></strong><span>{item.publishedAt ? `Published ${new Date(item.publishedAt).toLocaleString()}` : "Draft — not currently in effect"}</span></div></div>)}</div></div>; }
function StaffManager({ session, setMessage }) { const [staff, setStaff] = useState([]); const [form, setForm] = useState({ name: "", username: "", email: "", password: "", role: "admin" }); const [editing, setEditing] = useState(null); const load = async () => { const response = await fetch("/api/admin/staff"); if (response.ok) setStaff((await response.json()).staff); }; useEffect(() => { load(); }, []); const submit = async (event) => { event.preventDefault(); const response = await fetch(editing ? `/api/admin/staff/${editing.id}` : "/api/admin/staff", { method: editing ? "PATCH" : "POST", headers: { "Content-Type": "application/json", "X-CSRF-Token": session.csrfToken }, body: JSON.stringify(form) }); const data = await response.json(); if (!response.ok) return setMessage(data.error || "The staff account could not be saved."); setMessage(editing ? "Staff account updated." : "Staff access created."); setEditing(null); setForm({ name: "", username: "", email: "", password: "", role: "admin" }); await load(); }; return <div className="records-panel"><div className="records-heading"><div><h2>Staff access</h2><p>Create accounts for employees who need to use the admin portal.</p></div></div><form className="record-form" onSubmit={submit}><label><span>Name</span><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} /></label><label><span>Username</span><input required disabled={Boolean(editing)} value={form.username} onChange={(event) => setForm({ ...form, username: event.target.value })} /></label><label><span>Email</span><input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label><span>{editing ? "New password (optional)" : "Password"}</span><input required={!editing} minLength="12" type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} /></label><label><span>Access level</span><select value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}><option value="admin">Admin</option><option value="owner">Owner</option></select></label><button className="button primary-button" type="submit"><Check size={16} />{editing ? "Save staff account" : "Give access"}</button></form><div className="record-list">{staff.map((user) => <div className="record-row" key={user.id}><div><strong>{user.name} <span className="role-badge">{user.role}</span></strong><span>{user.username} · {user.email} · {user.active ? "Active" : "Inactive"}</span></div><button className="text-button" type="button" onClick={() => { setEditing(user); setForm({ name: user.name, username: user.username, email: user.email, password: "", role: user.role }); }}>Edit</button></div>)}</div></div>; }
function ResetPassword() { const token = new URLSearchParams(window.location.search).get("token") || ""; const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); const [complete, setComplete] = useState(false); const submit = async (event) => { event.preventDefault(); if (password !== confirm) return setError("The passwords do not match."); const response = await fetch("/api/admin/reset-password", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ token, password }) }); const data = await response.json(); if (!response.ok) return setError(data.error || "The password could not be reset."); setComplete(true); }; return <SimplePage title="Choose a new password">{complete ? <><p className="form-notice success">Your password has been changed.</p><a className="button primary-button" href="/admin">Return to sign in <ArrowRight size={17} /></a></> : <form className="account-card" onSubmit={submit}><p>Use at least 12 characters. This link can only be used once.</p><label><span>New password</span><input required minLength="12" type="password" value={password} onChange={(event) => setPassword(event.target.value)} /></label><label><span>Confirm password</span><input required minLength="12" type="password" value={confirm} onChange={(event) => setConfirm(event.target.value)} /></label><button className="button primary-button" type="submit">Change password <KeyRound size={17} /></button>{error && <p className="form-notice error">{error}</p>}</form>}</SimplePage>; }
function StatCard({ color, label, value }) { return <div className="stat-card"><span className={`status-dot ${color}`} /><div><strong>{value}</strong><span>{label}</span></div></div>; }
function Brand() { return <><span className="brand-mark"><span>N</span><span>IT</span></span><span><strong>Neno&apos;s</strong> IT repair</span></>; }
export default App;

function AccountPage() { return <div className="site-shell theme-dark"><header className="public-header"><a href="/" className="brand"><Brand /></a><nav className="public-nav is-open"><a href="/">Services</a><a href="/#pricing">Pricing</a><a href="/orders">Orders</a></nav></header><main><AccountPanel /></main></div>; }
function AccountVerification() { const token = new URLSearchParams(window.location.search).get("token") || ""; const [state, setState] = useState("loading"); const [error, setError] = useState(""); useEffect(() => { if (!token) { setState("error"); setError("This verification link is invalid or has expired."); return undefined; } fetch(`/api/account/verify?token=${encodeURIComponent(token)}`).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(data.error); setState("verified"); }).catch((err) => { setState("error"); setError(err.message || "This verification link is invalid or has expired."); }); return undefined; }, [token]); return <SimplePage title={state === "verified" ? "Email verified" : "Verify your email"}>{state === "loading" && <p>Checking your verification link...</p>}{state === "verified" && <><p className="form-notice success">Your email is verified. You can now sign in.</p><a className="button primary-button" href="/account">Go to your account <ArrowRight size={17} /></a></>}{state === "error" && <><p className="form-notice error">{error}</p><a className="button ghost-button" href="/account">Return to account</a></>}</SimplePage>; }
